import json
from decimal import Decimal
from pathlib import Path
root=Path(__file__).resolve().parents[2]
numeric=json.loads((root/'scripts/paperjs/numerical.json').read_text())['fixtures'];compound=json.loads((root/'scripts/paperjs/compound-paths.json').read_text())['fixtures']
def n(x):
 s=format(Decimal(repr(float(x))),'f');return s if '.' in s else s+'.0'
s=['''// Adapted from pinned Paper.js Numerical.js and CompoundPath.js.
// MIT license in upstream source files. Generated by generate-final-batches.py.
// Root queries deliberately exercise internal implementation, not public API.
import gleam/float
import gleam/io
import gleam/list
import gleam/option.{None}
import gleam/string
import svg_path
import svg_path/area
import svg_path/basic_shapes
import svg_path/internal/root
import svg_path/parse
fn emit_roots(id: String, values: Result(List(Float), root.Error)) {
 let output = case values {
  Ok(values) -> "Ok([" <> string.join(list.map(values,float.to_string),",") <> "])"
  Error(error) -> string.inspect(Error(error))
 }
 io.println(id <> ":" <> output)
}
pub fn main() {''']
for f in numeric:
 call=('Ok(root.quadratic('+','.join(n(c) for c in f['coefficients'])+'))') if f['method']=='solveQuadratic' else 'root.cubic('+','.join(n(c) for c in f['coefficients'])+')'
 s.append(f'emit_roots("numerical-{f["id"]}", {call})')
data=' '.join(('M' if c['method']=='moveTo' else 'L')+' '.join(n(v) for v in c['point']) for c in compound[0]['commands'])
s.append(f'let parsed = parse.path({json.dumps(data)})')
s.append('case parsed { Ok(path) -> io.println("compound-0:" <> string.inspect(list.length(svg_path.path_subpaths(path)))) Error(e) -> io.println("compound-0:" <> string.inspect(Error(e))) }')
for i,args in enumerate(compound[1]['rectangles']):
 (x,y),(w,h)=args
 s.append(f'let shape = basic_shapes.rect({n(x)},{n(y)},{n(w)},{n(h)},None,None)')
 s.append(f'case shape {{ Ok(sp) -> io.println("compound-{i+1}:" <> string.inspect(area.signed_subpath(sp) >. 0.0)) Error(e) -> io.println("compound-{i+1}:" <> string.inspect(Error(e))) }}')
s.append('}');(root/'test_paperjs/src/paper_final_batches_probe.gleam').write_text('\n'.join(s)+'\n')
